import{_ as i,o as t,c as a,a0 as s}from"./chunks/framework.jwovEGr5.js";const k=JSON.parse('{"title":"Flake policy","description":"","frontmatter":{},"headers":[],"relativePath":"testing/flake-policy.md","filePath":"testing/flake-policy.md"}'),n={name:"testing/flake-policy.md"};function l(o,e,r,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="flake-policy" tabindex="-1">Flake policy <a class="header-anchor" href="#flake-policy" aria-label="Permalink to &quot;Flake policy&quot;">​</a></h1><p>How sharecli treats intermittent test failures (C07 / L68).</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Keep CI signal high: a red job means a real regression, not noise.</li><li>Prefer root-cause fixes over retries.</li><li>When a flake is confirmed, quarantine it with an owner and expiry — never delete the test.</li></ul><h2 id="detection" tabindex="-1">Detection <a class="header-anchor" href="#detection" aria-label="Permalink to &quot;Detection&quot;">​</a></h2><ol><li><p><strong>CI retries</strong> — <code>.config/nextest.toml</code> <code>[profile.ci]</code> retries failed tests twice with a fixed 1s delay. Retries are a safety net, not a license to ignore flakes.</p></li><li><p><strong>Local reproduction</strong> — re-run the failing filter under load:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nextest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;test(&lt;name&gt;)&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run-ignored</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or hammer a suspect:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-features</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> break</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div></li><li><p><strong>Symptoms that count as flakes</strong> — pass/fail flip without code change; order-dependent failures; timing/sleep races; shared temp-dir / port collisions.</p></li></ol><h2 id="quarantine-process" tabindex="-1">Quarantine process <a class="header-anchor" href="#quarantine-process" aria-label="Permalink to &quot;Quarantine process&quot;">​</a></h2><ol><li>Open an issue titled <code>flake: &lt;test name&gt;</code> with OS, nextest/cargo output, and last green SHA.</li><li>Rename or gate the test so it is easy to filter (prefer a <code>#[ignore = &quot;flake: #NNNN&quot;]</code> with the issue number, or a name containing <code>_quarantine_</code>).</li><li>Add a nextest override only when needed (see <code>.config/nextest.toml</code> — keep overrides documented and temporary).</li><li>Assign an owner and a <strong>remove-by</strong> date (default: 14 days). Quarantine without an expiry is not allowed.</li><li>Fix or delete the quarantine entry in the same PR that lands the root-cause fix.</li></ol><h2 id="what-not-to-do" tabindex="-1">What not to do <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;What not to do&quot;">​</a></h2><ul><li>Do not widen CI retries globally to hide a known flake.</li><li>Do not skip the entire integration suite because one test is flaky.</li><li>Do not disable <code>RUSTFLAGS=-D warnings</code> or quality gates to “make green.”</li></ul><h2 id="bench-criterion-flakes-c08-l74" tabindex="-1">Bench / Criterion flakes (C08 / L74) <a class="header-anchor" href="#bench-criterion-flakes-c08-l74" aria-label="Permalink to &quot;Bench / Criterion flakes (C08 / L74)&quot;">​</a></h2><p>Perf jobs use short Criterion samples (<code>--sample-size 10</code>). Treat a gate failure as:</p><ol><li>Re-run <code>bench-gate</code> on the same SHA (Actions → Re-run failed jobs).</li><li>If it flips, open <code>flake: bench &lt;name&gt;</code> and temporarily raise that bench&#39;s <code>mean_ns</code> headroom in <code>docs/eval/baselines/criterion-baseline.json</code> <strong>with a measured note</strong> — never disable <code>bench-gate</code>.</li><li>Soft <code>criterion</code> job stays <code>continue-on-error: true</code> so advisory noise does not block merges; the hard gate is the quarantine surface.</li></ol><h2 id="related-recipes" tabindex="-1">Related recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to &quot;Related recipes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Role</th></tr></thead><tbody><tr><td><code>just test-nextest</code></td><td>Local run with <code>--profile ci</code> (retries + JUnit)</td></tr><tr><td><code>just test</code></td><td>Plain <code>cargo test</code> (no nextest retries)</td></tr><tr><td><code>just test-doc</code></td><td>Doctests (nextest does not run these)</td></tr></tbody></table><p>PR CI runs nextest/clippy/build on <strong>linux + macOS</strong> (<code>.github/workflows/ci.yml</code>). Windows matrix expansion is still deferred; flake triage on Windows remains manual until that lane lands.</p>`,16)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
